from __future__ import annotations

import json


def html(token: str, nonce: str) -> bytes:
    return _HTML.replace("__TOKEN__", json.dumps(token)).replace("__NONCE__", nonce).encode()


_HTML = r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Miku Dataset Review</title>
<style nonce="__NONCE__">
:root{color-scheme:dark;--bg:#0d1117;--panel:#161b22;--line:#30363d;--text:#e6edf3;--muted:#8b949e;--accent:#39c5bb;--danger:#f85149;--warn:#d29922}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,sans-serif}button,input,select,textarea{font:inherit;color:inherit;background:#0d1117;border:1px solid var(--line);border-radius:6px;padding:.55rem}button{cursor:pointer}button:hover,button:focus{border-color:var(--accent)}header{height:58px;display:flex;align-items:center;gap:1rem;padding:0 1rem;border-bottom:1px solid var(--line)}header h1{font-size:1rem;margin:0}.status{color:var(--muted)}main{display:grid;grid-template-columns:290px minmax(0,1fr);height:calc(100vh - 58px)}aside{border-right:1px solid var(--line);overflow:auto;padding:.75rem}.filters{display:grid;grid-template-columns:1fr 1fr;gap:.5rem;margin-bottom:.75rem}.queue{display:grid;gap:.4rem}.queue button{text-align:left}.queue button[aria-current=true]{border-color:var(--accent);background:#12302f}.queue small{display:block;color:var(--muted)}article{overflow:auto;padding:1rem;max-width:1280px}.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:1rem;margin-bottom:1rem}.card h2,.card h3{margin:.1rem 0 .75rem;font-size:1rem}.meta{display:flex;gap:.75rem;flex-wrap:wrap;color:var(--muted)}canvas{width:100%;height:150px;background:#090c10;border:1px solid var(--line);border-radius:6px}audio{width:100%;margin:.7rem 0}.controls,.decision{display:flex;align-items:center;gap:.6rem;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:.8rem}label{display:grid;gap:.3rem;color:var(--muted)}textarea{min-height:78px;resize:vertical;color:var(--text)}pre{white-space:pre-wrap;word-break:break-word;max-height:260px;overflow:auto;background:#0d1117;padding:.75rem;border-radius:6px}.accept{border-color:var(--accent)}.reject{border-color:var(--danger)}.quarantine{border-color:var(--warn)}.hidden{display:none!important}.error{color:#ff7b72}.ok{color:var(--accent)}kbd{border:1px solid var(--line);border-bottom-width:2px;border-radius:4px;padding:.1rem .3rem}@media(max-width:800px){main{grid-template-columns:1fr;height:auto}aside{border-right:0;border-bottom:1px solid var(--line);max-height:35vh}}
</style></head><body>
<header><h1>Miku Dataset Review</h1><span id="headline" class="status">queue loading…</span><span class="status">단건 검수 전용 · <kbd>Space</kbd> 재생 · <kbd>A/Q/R</kbd> 결정</span></header>
<main><aside><div class="filters"><select id="entity"><option value="audio">Audio</option><option value="persona">Persona</option></select><button id="reload">새로고침</button></div><div id="queue" class="queue"></div></aside>
<article><section id="empty" class="card">검수할 항목을 선택하세요.</section><div id="item" class="hidden">
<section class="card"><h2 id="title"></h2><div id="meta" class="meta"></div></section>
<section id="audioCard" class="card"><h3>Audio & waveform</h3><canvas id="wave" width="1200" height="150" aria-label="audio waveform"></canvas><audio id="audio" controls preload="metadata"></audio><div class="controls"><label>속도 <select id="speed"><option>.5</option><option>.75</option><option selected>1</option><option>1.25</option><option>1.5</option><option>2</option></select></label><label><input id="loop" type="checkbox">loop</label><label>zoom <input id="zoom" type="range" min="1" max="16" value="1"></label><span id="heard" class="status"></span></div><div class="grid"><label>segment start (ms)<input id="start" type="number" min="0"></label><label>segment end (ms)<input id="end" type="number" min="1"></label></div></section>
<section id="transcriptCard" class="card"><h3>Transcript</h3><div class="grid"><label>raw<textarea id="raw"></textarea></label><label>spoken<textarea id="spoken"></textarea></label><label>normalized<textarea id="normalized"></textarea></label></div></section>
<section id="personaCard" class="card hidden"><h3>Persona</h3><div class="grid"><label>prompt<textarea id="prompt" readonly></textarea></label><label>response<textarea id="response" readonly></textarea></label></div><label><input id="readComplete" type="checkbox">전체 내용을 읽고 판단함</label></section>
<section class="card"><h3>Evidence</h3><div class="grid"><div><strong>ASR comparison</strong><pre id="asr">없음</pre></div><div><strong>Alignment</strong><pre id="alignment">없음</pre></div><div><strong>Speaker</strong><pre id="speaker">없음</pre></div><div><strong>Quality / prosody</strong><pre id="quality">없음</pre></div><div><strong>Rights & provenance</strong><pre id="rights"></pre></div><div><strong>Persona dimensions / hard violation</strong><pre id="dimensions">없음</pre></div></div></section>
<section class="card"><h3>Review history</h3><pre id="history">없음</pre></section>
<section class="card"><h3>Decision</h3><div id="policy" class="status"></div><div class="grid"><label>Reviewer<input id="reviewer" autocomplete="name"></label><label>Reason<textarea id="reason" required></textarea></label></div><label><input id="adjudication" type="checkbox">disagreement adjudication</label><div class="decision"><button class="accept" data-decision="accept">Accept (A)</button><button class="quarantine" data-decision="quarantine">Quarantine (Q)</button><button class="reject" data-decision="reject">Reject (R)</button><span id="message"></span></div></section>
</div></article></main>
<script nonce="__NONCE__">
const TOKEN=__TOKEN__;const $=id=>document.getElementById(id);let queue=[],index=-1,current=null,reviewedMs=0,audioBuffer=null;
const pretty=v=>v==null?'없음':JSON.stringify(v,null,2);async function api(path,options={}){options.headers={...(options.headers||{}),'X-Review-Token':TOKEN};const r=await fetch(path,options);const body=await r.json();if(!r.ok)throw new Error(body.error||r.statusText);return body}
async function loadQueue(){try{queue=await api('/api/review-queue?entity_type='+$('entity').value);$('queue').replaceChildren(...queue.map((x,i)=>{const b=document.createElement('button');b.innerHTML=`${esc(x.title||x.entity_id)}<small>${esc(x.quality_tier||'')} · ${esc(x.latest_decision||'unreviewed')} · rev ${x.revision}</small>`;b.onclick=()=>loadItem(i);return b}));$('headline').textContent=`${queue.length} items`;if(queue.length)loadItem(Math.max(0,Math.min(index,queue.length-1)))}catch(e){$('headline').textContent=e.message}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function classify(items){const out={asr:[],alignment:[],speaker:[],quality:[]};for(const x of items||[]){const p=x.payload||{};(p.hypothesis?out.asr:p.token_intervals||p.word_intervals||p.phoneme_intervals?out.alignment:p.embedding?out.speaker:out.quality).push(p)}return out}
async function loadItem(i){index=i;current=await api(`/api/review-items/${queue[i].entity_type}/${queue[i].entity_id}`);reviewedMs=0;audioBuffer=null;$('readComplete').checked=false;$('adjudication').checked=false;$('reason').value='';$('empty').classList.add('hidden');$('item').classList.remove('hidden');document.querySelectorAll('.queue button').forEach((b,n)=>b.setAttribute('aria-current',n===i));$('title').textContent=current.title;$('meta').textContent=`${current.entity_type} · ${current.quality_tier||''} · ${current.training_status} · ${current.source.title}`;$('policy').textContent=current.double_review_required?'Gold double-review bucket: 독립 reviewer 2명이 필요합니다.':'단건 review evidence가 export gate에 기록됩니다.';$('history').textContent=pretty(current.reviews);$('rights').textContent=pretty({source:current.source,rights:current.rights,derived_objects:current.derived_objects});$('personaCard').classList.toggle('hidden',current.entity_type!=='persona');$('audioCard').classList.toggle('hidden',current.entity_type!=='audio');$('transcriptCard').classList.toggle('hidden',current.entity_type!=='audio');if(current.entity_type==='audio'){for(const k of ['raw','spoken','normalized'])$(k).value=current[k+'_text'];$('start').value=current.segment_start_ms;$('end').value=current.segment_end_ms;$('audio').src='/objects/'+current.playback_sha256;$('dimensions').textContent='없음';const c=classify(current.technical_evidence);for(const k of Object.keys(c))$(k).textContent=pretty(c[k]);$('audio').load();drawWave()}else{$('prompt').value=current.prompt;$('response').value=current.response;$('dimensions').textContent=pretty({dimensions:current.dimensions,hard_violation:current.hard_violation});for(const k of ['asr','alignment','speaker','quality'])$(k).textContent='없음'}$('message').textContent=''}
async function drawWave(){try{const data=await fetch($('audio').src).then(r=>r.arrayBuffer());audioBuffer=await new AudioContext().decodeAudioData(data);paint()}catch(e){$('message').textContent='waveform decode 실패: '+e.message}}
function paint(){if(!audioBuffer)return;const cv=$('wave'),ctx=cv.getContext('2d'),samples=audioBuffer.getChannelData(0),zoom=+$('zoom').value,center=($('audio').currentTime||0)/audioBuffer.duration,start=Math.max(0,Math.floor((center-.5/zoom)*samples.length)),end=Math.min(samples.length,Math.floor((center+.5/zoom)*samples.length)),step=Math.max(1,Math.floor((end-start)/cv.width));ctx.clearRect(0,0,cv.width,cv.height);ctx.strokeStyle='#39c5bb';ctx.beginPath();for(let x=0;x<cv.width;x++){let lo=1,hi=-1;for(let j=start+x*step;j<Math.min(end,start+(x+1)*step);j++){lo=Math.min(lo,samples[j]);hi=Math.max(hi,samples[j])}ctx.moveTo(x,(1+lo)*cv.height/2);ctx.lineTo(x,(1+hi)*cv.height/2)}ctx.stroke()}
function coveredMs(){let total=0;for(let i=0;i<$('audio').played.length;i++)total+=$('audio').played.end(i)-$('audio').played.start(i);return Math.round(total*1000)}$('audio').ontimeupdate=()=>{reviewedMs=coveredMs();$('heard').textContent=`reviewed media ${reviewedMs} ms`;if($('loop').checked&&$('audio').currentTime*1000>=+$('end').value){$('audio').currentTime=+$('start').value/1000;$('audio').play()}paint()};$('speed').onchange=()=>{$('audio').playbackRate=+$('speed').value};$('zoom').oninput=paint;
async function submit(decision){if(!current)return;const payload={entity_type:current.entity_type,entity_id:current.entity_id,decision,reviewer:$('reviewer').value,reason:$('reason').value,expected_revision:current.revision,evidence:{actor_type:'human',batch_size:1,media_reviewed_ms:reviewedMs,read_complete:$('readComplete').checked,adjudication:$('adjudication').checked}};if(current.entity_type==='audio')payload.edits={raw_text:$('raw').value,spoken_text:$('spoken').value,normalized_text:$('normalized').value,segment_start_ms:+$('start').value,segment_end_ms:+$('end').value};try{await api('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});$('message').className='ok';$('message').textContent='saved';await loadQueue()}catch(e){$('message').className='error';$('message').textContent=e.message}}
document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>submit(b.dataset.decision));$('reload').onclick=loadQueue;$('entity').onchange=()=>{index=0;loadQueue()};document.onkeydown=e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();$('audio').paused?$('audio').play():$('audio').pause()}else if(e.key.toLowerCase()==='a')submit('accept');else if(e.key.toLowerCase()==='q')submit('quarantine');else if(e.key.toLowerCase()==='r')submit('reject')};loadQueue();
</script></body></html>'''
